/* Anagram via a 26-slot count. Cast to unsigned char before ctype calls:
   passing a negative char is undefined behaviour. */
int isAnagram(const char *a, const char *b) {
    if (strlen(a) != strlen(b)) return 0;
    int cnt[26] = {0};
    for (int i = 0; a[i]; i++) { cnt[a[i] - 'a']++; cnt[b[i] - 'a']--; }
    for (int i = 0; i < 26; i++) if (cnt[i]) return 0;
    return 1;
}

